function DishCard({ name, price, spicy = false }) {
  return (
    <article className="card">
      <h3>{name}{spicy && " 🌶️"}</h3>
      <p>₦{price.toLocaleString()}</p>
    </article>
  )
}

function Section({ title, children }) {
  return (
    <section>
      <h2>{title}</h2>
      {children}
    </section>
  )
}

function Menu() {
  return (
    <main>
      <Section title="Rice">
        <DishCard name="Party jollof" price={3500} />
        <DishCard name="Fried rice" price={3500} />
      </Section>
      <Section title="Soups">
        <DishCard name="Egusi + pounded yam" price={4500} />
        <DishCard name="Pepper soup" price={3000} spicy />
      </Section>
    </main>
  )
}

ReactDOM.createRoot(document.getElementById("root")).render(<Menu />)
